    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    'e214eec7-6be7-48f4-b818-1f4cfb4379e1',
    '363bde4e-dd1e-40bc-b488-1801f4a86663',
    'Using the YendaNafe App: A Guide for CHWs',
    'Kugwiritsa Ntchito Pulogalamu ya YendaNafe: Thandizo la kwa Makhwao',
    'CHWs in Neno District found YendaNafe smartphone app improved task efficiency, replaced paper registers, '
    'and provided clinical decision support. The app served as an incentive and improved perceived professionalism.',
    'Makhwao ku Neno adapeza kuti pulogalamu ya YendaNafe imathandiza ntchito, '
    'imazichotsa mapepala, ndi kupereka chithandizo cha decision support.',
    '["Download and log into YendaNafe at the start of each workday", '
    '"Use the clinical decision support tools for every patient encounter", '
    '"Report any phone or app issues to your supervisor immediately", '
    '"Use the built-in scheduling to track upcoming home visits", '
    '"Share feedback with supervisors through the app dashboard"]'::jsonb,
    '["Tangirani ndi kulumikizana mu YendaNafe masiku onse a ntchito", '
    '"Gwiritsani ntchito zida za decision support kwa oxan oxan onse", '
    '"Lembani vuto lililonse la foni kapena pulogalamu kwa mutu wathu mwadzidzidzi", '
    '"Gwiritsani ntchito kalendala yomwe ili mu pulogalamu kukumbukira zoyenera kuchitira", '
    '"Gawilani ndi mutu wathu za zomwe mwapeza mu dashboard"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "CHW task efficiency improved", "evidence_strength": "moderate"}]'::jsonb,
    'chw_brief', 'digital_health', 'chw', 'info',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

