) ON CONFLICT DO NOTHING;

-- PNC: CHW Brief on Postnatal Care Gaps
INSERT INTO knowledge_assets (
    asset_id, study_id, title, title_chichewa,
    key_finding, key_finding_chichewa,
    actionable_takeaways, actionable_takeaways_chichewa,
    evidence_refs, asset_type, health_topic, audience, severity,
    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    '470549f2-ac90-4038-ba79-7ddf8493bc4d',
    '74eb84b2-7511-44a8-9d07-c625e6c5944e',
    'Postnatal Care: Why Timing Matters',
    'Chithandizo cha Komwe: Chifukwa Chake Nthawi Yofunika',
    'Only 3.2% of mothers in rural Malawi received postnatal care within 24 hours of delivery, '
    'despite 96% having a health facility within 10km. Health centers (not clinics) drive PNC uptake.',
    'Oyamba okha 3.2% ya amayi ku mzano adalandira chithandizo mofulumira, '
    'koma 96% ali ndi chipatala maulendo 10. Health centers (osati clinics) ndi zomwe zimathandiza.',
    '["CHWs should visit every mother within 24 hours of delivery — whether at home or facility", '
    '"Emphasize that the first week after delivery is the most dangerous for mother and baby", '
    '"Guide mothers to health centers (not just clinics) for postnatal check-ups", '
    '"Help mothers understand PNC is needed even if delivery went well", '
    '"Advocate for pre-discharge PNC for facility deliveries"]'::jsonb,
    '["Makhwao ayenera kufunsa amayi onse mkati mwa maora 24 atabereka", '
    '"Onetsani kuti sabata yoyamba ndi yopulumuka kwambiri kwa amayi ndi ana", '
    '"Thandizani amayi kupita kwa health centers (osati clinics) kuti azayang''ana", '
    '"Thandizani amayi kumvetsa kuti PNC ndiyofunika ngakhale kutsekereza kwakhuta", '
    '"Lembani za PNC musanatuluke ku chipatala ngati amayi atabereka kumene"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "PNC within 24h very low", "evidence_strength": "strong", "value": "3.2%"}]'::jsonb,
    'chw_brief', 'maternal_health', 'chw', 'warning',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

