) VALUES (
    '60157ebc-c171-4cfa-94ea-54c1fbbb33de',
    '65320254-bbfd-4251-b852-ea77716766b9',
    'Feeding Your Baby Right: What the Research Shows',
    'Kudyetsa Mwana Wanu Mwachizolowezi: Zomwe Kafukufuku Amawonetsa',
    '30.8% of children under 2 in Malawi are stunted. Only 32% receive minimum dietary diversity. '
    'Mothers with higher wealth, radio exposure, and normal BMI have children with better feeding practices.',
    '30.8% ya ana ku Malawi ndi okhutira. Okha 32% amalandira zakudya zosiyanasiyana. '
    'Amayi olemera, amene amamva pulogalamu za mafoni, ndi ali ndi thupi labwino ndi omwe amadyetsa ana bwino.',
    '["Start complementary feeding at 6 months — not earlier, not later", '
    '"Include foods from at least 4 food groups at each meal for minimum dietary diversity", '
    '"Continue breastfeeding alongside complementary foods up to 2 years", '
    '"Listen to radio health programs for feeding advice", '
    '"If you had a caesarean section, seek help to start breastfeeding early"]'::jsonb,
    '["Yambitsani zakudya zowonjezera pa miyesi 6 — osati kale, osati chifukwa", '
    '"Ikani zakudya kuchokera ku magulu osachepera 4 pa chakudya chilichonse", '
    '"Pitirizani kudyetsa mphenyo pamodzi ndi zakudya zowonjezera mpaka zaka 2", '
    '"Mverani malangizo a pa foni za zakudya", '
    '"Ngati mwabereka ndi ma operation, funsani thandizo kuyambitsa kudyetsa mphenyo mwamsanga"]'::jsonb,
    '[{"takeaway_index": 1, "stat_ref": "Minimum dietary diversity", "evidence_strength": "strong", "value": "32%"}]'::jsonb,
    'chw_brief', 'nutrition', 'chw', 'warning',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

