) VALUES (
    '8be0e42d-36b5-45e4-abf2-d6a2b15da0e7',
    '65320254-bbfd-4251-b852-ea77716766b9',
    'Stunting in Malawi: A Call to Action',
    'Kukhutira ku Malawi: Chithandizo cha Kuchita',
    '30.8% of children under 24 months are stunted in Malawi. 40% are not exclusively breastfed to 6 months. '
    'Only 12% meet minimum acceptable diet. Wealth, education, and media exposure are key determinants.',
    '30.8% ya ana ku Malawi ndi okhutira. 40% sangadye mphenyo kokha mpaka miyesi 6. '
    'Okha 12% amadye zakudya zokwanila. Umasanje, chiphunzitso, ndi mafoni ndi zofunika.',
    '["Breastfeed exclusively for the first 6 months — no water, no other foods", '
    '"After 6 months, add soft foods from 4+ food groups while continuing to breastfeed", '
    '"Include protein (beans, fish, eggs), vegetables, fruits, and grains in every meal", '
    '"Visit the health center for growth monitoring every month", '
    '"If your child is not growing well, ask about therapeutic feeding programs"]'::jsonb,
    '["Dyetsani mphenyo kokha kwa masabata 6 — madzi kapena zakudya zina", '
    '"Tsopano pa miyesi 6, onjezani zakudya zapafupi kuchokera kwa magulu 4+", '
    '"Ikani protheni (khungu, nsomba, anambo, masamba, zipatso, ndi ulimi pa chakudya chilichonse", '
    '"Pitani ku chipatala kuwunira kukula kwa mwana mwezi ndi mwezi", '
    '"Ngati mwana saukula, funsani za malangizo a zakudya achipatala"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "Exclusive breastfeeding rate", "evidence_strength": "strong", "value": "60%"}]'::jsonb,
