) VALUES (
    '894d38a5-c168-46f1-8949-8e78f06cb51f',
    '65320254-bbfd-4251-b852-ea77716766b9',
    'Breast is Best: Give Your Baby the Right Start',
    'Mphenyo Ndi Wabwino: Patsani Mwana Wanu Chiyambiro Choyenera',
    '78% of Malawian mothers breastfeed within 1 hour, but 40% stop exclusive breastfeeding before 6 months. '
    'Caesarean section reduces early breastfeeding initiation by 68%.',
    '78% ya amayi a ku Malawi amadyetsa mphenyo mkati mwa maora 1, koma 40% amasiya kudyetsa mphenyo yokha. '
    'Kupereka ndi ma operation kumachepesa kuyambitsa kudyetsa mphenyo.',
    '["Start breastfeeding within 1 hour of birth — this is the golden hour", '
    '"Give ONLY breast milk for the first 6 months — no water, no formula, no other foods", '
    '"If you had a caesarean, ask for help to breastfeed in the recovery room", '
    '"Continue breastfeeding alongside other foods up to age 2", '
    '"Breastfeeding protects your baby from diarrhea, pneumonia, and malnutrition"]'::jsonb,
    '["Yambitsani kudyetsa mphenyo mkati mwa maora 1 atabadwa — nthawi yoyenera", '
    '"Patsani mphenyo kokha kwa masabata 6 — madzi, formula, kapena zakudya zina zisakhalepo", '
    '"Ngati mwabereka ndi ma operation, funsani thandizo kudyetsa mphenyo ku recovery room", '
    '"Pitirizani kudyetsa mphenyo pamodzi ndi zakudya zina mpaka zaka 2", '
    '"Kudyetsa mphenyo kumatchedwa mwana ku matenda a kunyansa ndi kupuma"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "Early breastfeeding initiation", "evidence_strength": "strong", "value": "78%"}]'::jsonb,
    'poster', 'nutrition', 'community', 'info',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- Malaria: CHW Brief on Bed Net Protection
INSERT INTO knowledge_assets (
    asset_id, study_id, title, title_chichewa,
    key_finding, key_finding_chichewa,
    actionable_takeaways, actionable_takeaways_chichewa,
    evidence_refs, asset_type, health_topic, audience, severity,
    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    'f2c96047-75d1-45bd-92e3-5cd697e03cab',
    '6230872c-4510-4dd9-aa2a-2c7bcbd697b2',
    'Bed Nets Protect Everyone: Not Just the Sleeper',
    'Makuta Amatchedwa Anthu Onse — Osati Okha Okhalamo',
    'Universal bed net campaigns reduced malaria from 28.4% to 15.0% in pregnant women. '
    'The protection works at community level — even if an individual doesn''t always use a net, '
    'widespread use reduces everyone''s risk.',
    'Makuta a ana onse adachepetsa malungo kuchoka ku 28.4% kupita ku 15.0%. '
    'Chitetezo chimagwira ntchito pa gulu lonse — ngakhale munthu samagwiritsa ntchito makuta nthawi zonse.',
    '["Sleep under a bed net every night — especially if pregnant or have young children", '
    '"Use the net from the first month of pregnancy — malaria is most dangerous early on", '
    '"Make sure the net is tucked in properly — no gaps for mosquitoes to enter", '
    '"Repair holes in nets immediately or request replacement", '
    '"Encourage everyone in the household to sleep under nets — community protection matters"]'::jsonb,
    '["Gonani pansi pa makuta usiku — makamaka ngati muli ndi mimba kapena ana ang''ono", '
    '"Gwiritsani ntchito makuta kuyambira tsiku loyamba la mimba — malungo ndi owopsya kwambiri", '
    '"Onetsetsani kuti makuta ali bwino — pali mipata yomwe ingalole nyungwe kulowa", '
    '"Konzeza mipata mu makuta mwadzidzidzi kapena funsani kusinthidwa", '
    '"Limbikitsani anthu onse m''banja kugonera pansi pa makuta — chitetezo cha gulu ndi chofunika"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "Malaria prevalence declined post-campaign", "evidence_strength": "strong", "value": "28.4% to 15.0%"}]'::jsonb,
    'chw_brief', 'malaria', 'chw', 'warning',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- Malaria: Infographic on Spatial Clusters
INSERT INTO knowledge_assets (
    asset_id, study_id, title, title_chichewa,
    key_finding, key_finding_chichewa,
    actionable_takeaways, actionable_takeaways_chichewa,
    evidence_refs, asset_type, health_topic, audience, severity,
    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    'dbcf5645-d5aa-4482-ba29-3b87e780a1a3',
    'b81dce6f-9a7f-43dd-8fbd-fbdd051586c0',
    'Malaria Hotspots: Why Some Households Get Sick More Often',
    'Malungo a Malo: Chifukwa Chake Ena Amamankhwala Kwambiri',
    'In rural Chikhwawa, 57.1% of children had at least one malaria case in a year. '
    'Repeated infections cluster in specific households near mosquito breeding sites. '
    'Poverty increases risk. ITN coverage was only 38% — well below the national target.',
    'Ku Chikhwawa, 57.1% ya ana anali ndi malungo ochepa pang''ono mu chaka chimodzi. '
    'Matenda amabwerera kwambiri kuma household ofunikira kumene nyungwe zimadzala. '
    'Umasanje sungaulepetsa. Makuta anali 38% okha.',
    '["Check which households in your catchment have repeated malaria cases — focus visits there", '
    '"Ensure every child sleeps under a treated net, especially during rainy season", '
    '"Empty standing water around the house — mosquito breeding sites increase risk", '
    '"Seek treatment immediately if a child has fever — don''t wait more than 24 hours", '
    '"Households with open eaves and grass roofs are higher risk — advise on screening"]'::jsonb,
    '["Yang''anani ma household omwe ali ndi malungo ochulukirachi — lemekezani kwawo", '
    '"Onetsetsani kuti ana onse amagonera pansi pa makuta, makamaka mu nyengo ya mvula", '
    '"Chotsani madzi ozizira pafupi ndi nyumba — kumene nyungwe zimadzala zimawonjezera ngozi", '
    '"Pitani ku chipatala mwadzidzidzi ngati mwana ali ndi chifuwa — musayembekezere masiku 24", '
    '"Ma household omwe ali ndi mpweya wotseguka ndi denga la masamba ndi oopsya — langizani za screen"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "Cumulative incidence", "evidence_strength": "strong", "value": "57.1%"}]'::jsonb,
    'infographic', 'malaria', 'chw', 'warning',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- TB: CHW Brief on TB Case Detection
INSERT INTO knowledge_assets (
    asset_id, study_id, title, title_chichewa,
    key_finding, key_finding_chichewa,
    actionable_takeaways, actionable_takeaways_chichewa,
    evidence_refs, asset_type, health_topic, audience, severity,
    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    'e7dfa4c0-0276-4bf8-92f9-7920f005d033',
    'dc2c3acf-f6a9-4231-a06e-aa9cc7946ebb',
    'TB in Malawi: Finding the Missing Cases',
    'Matenda a TB ku Malawi: Kupezera Odwala Omwe Ali ndi Matenda',
    'Malawi reported 18,025 new TB cases in 2022 — a 17.2% increase from 2018. '
    'Treatment success improved to 89.2%, but men aged 35-64 have the highest rates. '
    'COVID-19 disrupted TB services, causing cases to be missed.',
    'Malawi inawuza odwala 18,025 a TS pa 2022 — kuwonjezera 17.2%. '
    'Kuchira bwino kwenikweni kufika ku 89.2%, koma athanzi a 35-64 ndi omwe ali ndi matenda awiri. '
    'COVID-13 inawononga ntchito za TB.',
    '["Ask about cough lasting more than 2 weeks — this is the key TB symptom", '
    '"Refer anyone with cough + fever + weight loss for TB testing immediately", '
    '"Remind patients that TB treatment takes 6 months — stopping early causes drug resistance", '
    '"Screen household contacts of TB patients — TB spreads through the air", '
    '"COVID-19 disrupted TB services — catch up on missed screenings now"]'::jsonb,
    '["Funsani za kasumiro komwe kumene kumakhala masabata osachepera 2 — ndi chizindikiro cha TB", '
    '"Tumizani aliyense ali ndi kasumiro + chifuwa + kuchepa kwa thupi kuti ayesenso TB mwadzidzidzi", '
    '"Limbikitsani odwala kuti matenda a TB amatha masabata 6 — kusiya pang''ono kumapangitsa kunana", '
    '"Sewerani ana a banja la odwala TB — TB imafalikira mu mpweya", '
    '"COVID-13 inawononga ntchito za TB — tsatirirani zosakwanira zilizonse"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "TB cases increased 17.2%", "evidence_strength": "strong", "value": "18,025 in 2022"}]'::jsonb,
    'chw_brief', 'tb', 'chw', 'warning',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- TB/HIV: CHW Brief on Integration
INSERT INTO knowledge_assets (
    asset_id, study_id, title, title_chichewa,
    key_finding, key_finding_chichewa,
    actionable_takeaways, actionable_takeaways_chichewa,
    evidence_refs, asset_type, health_topic, audience, severity,
    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    'c499edd7-2e0e-495c-8194-59d0b2d4ca26',
    '6193bacd-b8ab-4da4-955a-1f43f9867a0b',
    'TB and HIV: Two Diseases, One Patient',
    'TB ndi HIV: Matenda Awiri, Munthu Mmodzi',
    'At Lighthouse Trust in Lilongwe, 66.5% of TB patients were HIV co-infected. '
    'HIV testing and ART uptake among TB patients is high and improving. '
    'Delays in ART initiation persist and need to be addressed.',
    'Ku Lighthouse Trust ku Lilongwe, 66.5% ya odwala TB anali ndi HIV. '
    'Kuyeza HIV ndi kuyamba ART kwa odwala TB ndi kwambiri ndi kukula. '
    'Kuchedwa kuyamba ART kumafunika kuthetsedwa.',
    '["Every TB patient should be tested for HIV — and every HIV patient screened for TB", '
    '"ART should start as soon as possible after TB treatment begins — don''t wait", '
    '"TB patients on ART have higher relapse rates — monitor closely", '
    '"Children with TB may have different symptoms than adults — look for failure to thrive", '
    '"Report any TB patient who stops treatment — defaulters need follow-up"]'::jsonb,
    '["Odwala onse a TB ayenera kuyesedwa HIV — ndi odwala HIV onse ayenera kuyezedwa TB", '
    '"ART ayenera kuyamba motere pamene matenda a TB ayamba — musayembekezere", '
    '"Odwala TB ali ndi ART ali ndi mwayi wobwerezeredwa — yang''anirani bwino", '
    '"Ana ali ndi TB ali ndi zizindikiro zosiyana ndi anthu aakulu — funsani za kulephera kukula", '
    '"Lembani ngati odwala TB ali ndi kulephera — odwala omwe ali ndi kulephera afuna kutsatiridwa"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "HIV co-infection rate", "evidence_strength": "strong", "value": "66.5%"}]'::jsonb,
    'chw_brief', 'tb', 'chw', 'warning',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- HIV: Poster on 95-95-95 Targets
INSERT INTO knowledge_assets (
    asset_id, study_id, title, title_chichewa,
    key_finding, key_finding_chichewa,
    actionable_takeaways, actionable_takeaways_chichewa,
    evidence_refs, asset_type, health_topic, audience, severity,
    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    '099ce541-6542-4de1-be47-7addf30ee676',
    '0d03a7ef-4313-4b75-9e1e-187182dfac62',
    'Know Your Status: The 95-95-95 Targets',
    'Dziwani Mwatsimikizi: 95-95-95',
    'Malawi aims to end AIDS as a public health threat by 2030 through 95-95-95 targets: '
    '95% of people with HIV know their status, 95% of those diagnosed are on ART, '
    '95% of those on ART have suppressed viral load.',
    'Malawi imafuna kupha AIDZI ngati vuto la zaumoyo wa publangi pofika 2030: '
    '95% ya anthu ali ndi HIV adziwa chowonadi, 95% ya omwe adayezedwa ali pa ART, '
    '95% ya omwe ali pa ART ali ndi viral load yochepa.',
    '["Get tested for HIV — knowing your status is the first step", '
    '"If positive, start ART immediately — treatment keeps you healthy and prevents transmission", '
    '"Take ART every day without missing doses — this suppresses the virus", '
    '"Bring your partner for testing — couples testing saves lives", '
    '"New prevention options like injectable cabotegravir are now available"]'::jsonb,
    '["Yesezani HIV — kudziwa chowonadi ndi sitepu yoyamba", '
    '"Ngati muli ndi HIV, yambitsani ART mwadzidzidzi — chithandizo chimakuthandizani kukhala ndi umoyo", '
    '"Mwayeretsani ART tsiku lililonse — chimenechi chimachepetsa virus", '
    '"Bweretsani mnzanu kuti ayesenwe — kuyeza pamodzi kumapulumutsa moyo", '
    '"Njira zatsopano za chitetezo ngati cabotegravir zaperekedwa kale"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "95-95-95 targets", "evidence_strength": "policy", "value": "national target"}]'::jsonb,
    'poster', 'hiv', 'community', 'info',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- PBF: Infographic on Equipment Availability
INSERT INTO knowledge_assets (
    asset_id, study_id, title, title_chichewa,
    key_finding, key_finding_chichewa,
    actionable_takeaways, actionable_takeaways_chichewa,
    evidence_refs, asset_type, health_topic, audience, severity,
    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    'f37d9b54-b859-4e50-bc42-e2ca753dd2ed',
    '92d3a187-79a0-46ad-a440-80636dae58d6',
    'Better Equipment Saves Mothers: The PBF Story',
    'Zida Zabwino Zimachedwa Amayi: Nkhani ya PBF',
    'Performance-based financing in Malawi improved availability of essential obstetric equipment: '
    'delivery kits +29pp, suturing kits +49pp, stethoscopes +52pp. '
    'Financial incentives tied to performance targets drove improvements.',
    'Kulipira pa ntchito ku Malawi kunawonjezera zida zaobitsira: '
    'zida zobitsira +29pp, zida zosutura +49pp, stethoscopes +52pp. '
    'Malipiro a ndalama zokhazikika pa zofunika za ntchito anathandiza.',
    '["Facilities should track their equipment availability monthly", '
    '"Report missing equipment to supervisors — don''t wait for quarterly reviews", '
    '"Delivery kits should be available at every facility where deliveries happen", '
    '"Clean and maintain equipment regularly — broken equipment is as bad as missing equipment", '
    '"Advocate for PBF-style accountability in your facility"]'::jsonb,
    '["Ma facility ayenera kuyang''ana zida zawo mwezi ndi mwezi", '
    '"Lembani za zida zosakwanira kwa mutu wathu — musayembekezere masabata 4", '
    '"Zida zobitsira ziyenera kukhala pa facility iliyonse yobitsira", '
    '"Sambani ndi kusunga zida pafupipafupi — zida zopweteka ndi zofanana ndi zosakwanira", '
    '"Lembani za kulipira pa ntchito monga njira yowunikirira mu facility yanu"]'::jsonb,
    '[{"takeaway_index": 2, "stat_ref": "PBF improved delivery kit availability", "evidence_strength": "strong", "value": "+29pp"}]'::jsonb,
    'infographic', 'maternal_health', 'dho,supervisor', 'info',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- Malaria: Infographic on 20-Year Decline
INSERT INTO knowledge_assets (
    asset_id, study_id, title, title_chichewa,
    key_finding, key_finding_chichewa,
    actionable_takeaways, actionable_takeaways_chichewa,
    evidence_refs, asset_type, health_topic, audience, severity,
    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    '3392e962-b0bb-4433-bbbe-365de2436b52',
    '757bc45d-8757-4cdd-964a-cb4d34758379',
    'Malaria in Malawi: 20 Years of Progress',
    'Malungo ku Malawi: Zaka 20 za Kukula',
    'National malaria prevalence in children declined from 43.93% (2000) to 19.2% (2022). '
    'This 56% reduction is attributed to bed nets, ACTs, the RTS,S malaria vaccine, and IRS. '
    'Hotspots remain around Lake Malawi and central region.',
    'Malungo ku Malwu adachepa kuchoka ku 43.93% (2000) kupita ku 19.2% (2022). '
    'Kuchepetsa kumeneku ndi kwa makuta, ACTs, rotha ya malungo RTS,S, ndi IRS. '
    'Malo okhwidwa ali pafupi ndi Nyanja ya Malawi ndi gawo la pakati.',
    '["Malaria is declining but not gone — keep using bed nets every night", '
    '"Get your children vaccinated against malaria when the vaccine is available", '
    '"Seek treatment within 24 hours of fever — ACTs are effective and free", '
    '"Community-wide net use matters more than individual use — protect your neighbors too", '
    '"Report if you notice more mosquitoes or more malaria cases in your area"]'::jsonb,
    '["Malungo akuchepa koma sangathe — pitirizani kugonera pansi pa makuta usiku", '
    '"Dzipatsani ana inu rotha ya malungo ngati ilipo", '
    '"Pitani ku chipatala mkati mwa maora 24 ali ndi chifuwa — ACT ndi yothandiza ndi yaulere", '
    '"Kugonera pansi pa makuta kwa anthu onse ndikofunika kuposa kwa munthu mmodzi — tetezani anzathu", '
    '"Lembani ngati mukuona nyungwe zambiri kapena malungo ambiri m''galamoyi"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "National PfPR decline", "evidence_strength": "strong", "value": "43.93% to 19.2%"}]'::jsonb,
    'infographic', 'malaria', 'community', 'info',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

