    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    '21b26a48-d5e7-4e52-801a-25ab9df5cc17',
    '5fcff5ba-5a80-48f0-bcd9-d526e65e9a03',
    'Universal Health Coverage: Health for All Malawians',
    'Chitetezo cha Zaumoyo: Zaumoyo kwa Alionse wa Malawi',
    'Malawi''s National Health Policy aims for Universal Health Coverage by 2030. '
    'Six priority areas: Service Delivery, Preventive Health, Leadership, Financing, HRH, and Medicines. '
    'Progress during MDGs but gaps remain in quality and equitable access.',
    'Boma la Malawi lifuna UHC pofika 2030. '
    'Zolinga 6: Kupereka ntchito, Kupewa matenda, Utumiki, Kusunga ndalama, HRH, ndi Mankhwala. '
    'Kukula kunali koma mipata ili koma bwino ndi kufika mosiyana.',
    '["Every Malawian has the right to quality health care — know your rights", '
    '"The Essential Health Package covers key services — ask what is available at your facility", '
    '"Prevention is cheaper than treatment — invest in clean water, nutrition, and immunization", '
    '"Report facilities that charge for services that should be free", '
    '"Community health workers are part of the health system — support them"]'::jsonb,
    '["Alionse wa Malawi ali ndi ufulu wa zaumoyo zabwino — dziwani ufulu wanu", '
    '"Essential Health Package imaphatikiza ntchito zofunika — funsani zilipo pa facility yanu", '
    '"Kupewa ndi kotsatira kwa chithandizo — thandizani madzi oyera, zakudya, ndi machiritso", '
    '"Lembani ma facility omwe amalipira ntchito zoyenera kukhala zaulere", '
    '"Makhwao ndi gawo la thupi la zaumoyo — thandizani awa"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "UHC target", "evidence_strength": "policy", "value": "2030"}]'::jsonb,
    'poster', 'maternal_health', 'community', 'info',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

