    synthesized_at, synthesized_by, confidence_level, status, created_at, updated_at
) VALUES (
    '4750ee23-fbe9-435a-a74e-8cc003390de6',
    'ba9f3b48-9266-44f0-85a4-fdb846a64dea',
    'Where HIV Money Goes: Malawi''s Spending Assessment',
    'Kumene Ndalama za HIV Zimapita: Kuyeza Kwa Malawi',
    'Malawi''s National AIDS Spending Assessment tracks HIV funding across 5 programme pillars: '
    'prevention, testing, care & treatment, social protection, and programme enablers. '
    'Understanding spending helps ensure resources reach those who need them most.',
    'Kuyeza kwa Malawi kumayang''ana ndalama za HIV m''mitundu 5: '
    'kupewa, kuyeza, chithandizo, chitetezo, ndi zothandizira. '
    'Kumvetsa kugwiritsa ntchito ndalama kumathandiza kuti zida zifike kwa omwe afunika kwambiri.',
    '["Community members can ask how HIV funds are used in their district", '
    '"Ensure prevention programmes include young people — they are a key population", '
    '"Support social protection programmes for people living with HIV", '
    '"Advocate for transparent reporting of HIV spending at district level", '
    '"Hold leaders accountable for using HIV funds as intended"]'::jsonb,
    '["Anthu a m''mudzi amatha funsa momwe ndalama za HIV zigwiritsidwira ntchito m''district yawo", '
    '"Onetsetsani kuti mapulogalamu a kupewa aphatikiza anthu a achinyamata — ndi gulu lofunika", '
    '"Thandizani mapulogalamu a chitetezo kwa anthu ali ndi HIV", '
    '"Lembani za kulemekezedwa kwa ndalama za HIV pa level ya district", '
    '"Yang''anirani anzawa kuti ndalama za HIV zigwiritsidwe ntchito monga zalandilidwa"]'::jsonb,
    '[{"takeaway_index": 0, "stat_ref": "Spending assessed across 5 pillars", "evidence_strength": "policy"}]'::jsonb,
    'infographic', 'hiv', 'dho,community', 'info',
    '2026-08-26T02:08:29.061061+00:00', 'samala_pipeline', 'high', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;


