-- Nutrition: Guide on Child Feeding
-- Rerun-safe: drop any older same-title guide first (public list stays deduped).
DELETE FROM self_care_guides WHERE title = 'How to Feed Your Child: A Guide for Mothers';
INSERT INTO self_care_guides (
    guide_id, title, title_chichewa, category, audience, severity,
    what_it_is, what_it_is_chichewa,
    what_to_do_now, what_to_do_now_chichewa,
    what_not_to_do, what_not_to_do_chichewa,
    when_to_seek_help, when_to_seek_help_chichewa,
    prevention, prevention_chichewa,
    treatment_limitations, treatment_limitations_chichewa,
    clinical_decision_points, clinical_decision_points_chichewa,
    source, last_reviewed, is_active, created_at, updated_at
) VALUES (
    'f9424e83-ac4a-4dd4-bede-b58037007b3c',
    'How to Feed Your Child: A Guide for Mothers',
    'Momwe Mungadyetse Mwana Wanu: Thandizo kwa Amayi',
    'nutrition', 'chw,community', 'warning',
    'Child undernutrition affects 30.8% of children under 24 months in Malawi. '
    'Stunting (low height for age) means the child is not growing properly. '
    'It is caused by poor feeding practices, not enough food, or repeated illness.',
    'Kukhutira kuma khudza ana 30.8% ali ndi miyesi 24 pansi ku Malawi. '
    'Kukhutira kunenera kuti mwana saukula bwino. '
    'Chimene chimayambitsa ndi zakudya zosayenera, zakudya zochepa, kapena matenda nthawi zonse.',
    '["If your child is under 6 months: breastfeed ONLY, no water or other foods", '
    '"If 6-8 months: breastfeed + soft foods like porridge with groundnuts, mashed banana, mashed beans", '
    '"If 9-23 months: breastfeed + 3 meals/day + 2 snacks from 4+ food groups", '
    '"Take your child for growth monitoring at the health center every month", '
    '"If your child has diarrhea: continue feeding + ORS + zinc for 10-14 days"]'::jsonb,
    '["Ngati mwana ali ndi miyesi 6 pansi: dyetsani mphenyo kokha — madzi kapena zakudya zina zisakhalepo", '
    '"Ngati 6-8 miyesi: mphenyo + zakudya zapafupi ngati phala ndi ma groundnuts, banana, khungu", '
    '"Ngati 9-23 miyesi: mphenyo + zakudya za masiku 3 + zakudya zina za masiku 2 kuchokera kwa magulu 4+", '
    '"Bweretsani mwana ku chipatala kuwunira kukula kwa mwezi ndi mwezi", '
    '"Ngati mwana ali ndi kunyansa: pitirizani kudyetsa + ORS + zinc kwa masabata 10-14"]'::jsonb,
    '["Don''t give water to babies under 6 months — it fills their stomach but has no nutrition", '
    '"Don''t skip meals — malnourished children need MORE food, not less", '
    '"Don''t give only porridge — it needs to be mixed with protein and vegetables", '
    '"Don''t stop breastfeeding when the child gets sick — breast milk is medicine", '
    '"Don''t wait until the child is very thin to seek help — early action saves lives"]'::jsonb,
    '["Musapatsi madzi ana oposa miyesi 6 — amadzaza m''mimba koma mulibe zakudya", '
    '"Musasiye zakudya — ana obvutika ndi zakudya afunika zakudya ZAMBIRI, osati zochepa", '
    '"Musagwiritse phala lokha — ayenera kukhala ndi protheni ndi masamba", '
    '"Musasiye kudyetsa mphenyo ngati mwana ali ndi matenda — mphenyo ndi mankhwala", '
    '"Musayembekezere kufika pamene mwana ali wofooka kwambiri — kuchita mwamsanga kumapulumutsa moyo"]'::jsonb,
    'Seek help immediately if: child refuses to eat for more than 2 days; '
    'child has sunken eyes, dry mouth, or no tears when crying; '
    'child is very sleepy or difficult to wake; child has blood in stool.',
    'Funsani thandizo mwadzidzidzi ngati: mwana sakufuna kudya masiku 2 kapena kuposa; '
    'mwana ali ndi maso obiriwira, mnku wouma, kapena mliriryo osakhala; '
    'mwana ali ndi tulo tachilendo kapena sazikonzekera; mwana ali ndi magazi mmenemo.',
    '["Exclusive breastfeeding for 6 months — the single most important intervention", '
    '"Introduce diverse foods from 6 months — not just porridge", '
    '"Monthly growth monitoring catches problems early", '
    '"Zinc + ORS for diarrhea prevents malnutrition from worsening", '
    '"Vitamin A supplementation twice yearly strengthens immunity"]'::jsonb,
    '["Kudyetsa mphenyo yokha kwa masabata 6 — ntchito yofunika kwambiri", '
    '"Yambitsani zakudya zosiyanasiyana kuyambira miyesi 6 — osati phala lokha", '
    '"Kuwunira kukula kwa mwezi ndi mwezi kumapeza mavuto mwamsanga", '
    '"Zinc + ORS ya kunyansa imalepheritsa kukhutira kuukhululukira", '
    '"Mankhwala a Vitamin A awiri pa chaka amathandiza chitetezo cha thupi"]'::jsonb,
    '[{"trigger": "MUAC < 11.5 cm", "action": "Refer to therapeutic feeding program (OTP)", "evidence": "Severe acute malnutrition"}, {"trigger": "Weight-for-age Z-score < -2", "action": "Intensify feeding counseling, monthly follow-up", "evidence": "Underweight indicator from MDHS"}]'::jsonb,
    '[{"trigger": "MUAC < 11.5 cm", "action": "Tumizani ku pologalamu ya zakudya achipatala (OTP)", "evidence": "Kukhutira kwakukulu"}, {"trigger": "Z-score ya bulukwa pa miyesi < -2", "action": "Wonjezani malangizo a zakudya, kutsatiridwa kwa mwezi", "evidence": "Chizindikiro cha kukhutira kuchoka ku MDHS"}]'::jsonb,
    '[{"trigger": "MUAC < 11.5 cm", "action": "Refer to therapeutic feeding program (OTP)", "evidence": "Severe acute malnutrition"}, {"trigger": "Weight-for-age Z-score < -2", "action": "Intensify feeding counseling, monthly follow-up", "evidence": "Underweight indicator from MDHS"}]'::jsonb,
    '[{"trigger": "MUAC < 11.5 cm", "action": "Tumizani ku pologalamu ya zakudya achipatala (OTP)", "evidence": "Kukhutira kwakukulu"}, {"trigger": "Z-score ya bulukwa pa miyesi < -2", "action": "Wonjezani malangizo a zakudya, kutsatiridwa kwa mwezi", "evidence": "Chizindikiro cha kukhutira kuchoka ku MDHS"}]'::jsonb,
    'Walters et al. 2019 BMC Public Health; MDHS 2015-16; WHO IYCF guidelines',
    '2026-08-26T02:08:29.061061+00:00', TRUE, '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- TB: Guide on Recognising TB
-- Rerun-safe: drop any older same-title guide first (public list stays deduped).
DELETE FROM self_care_guides WHERE title = 'Recognising Tuberculosis: What You Need to Know';
INSERT INTO self_care_guides (
    guide_id, title, title_chichewa, category, audience, severity,
    what_it_is, what_it_is_chichewa,
    what_to_do_now, what_to_do_now_chichewa,
    what_not_to_do, what_not_to_do_chichewa,
    when_to_seek_help, when_to_seek_help_chichewa,
    prevention, prevention_chichewa,
    treatment_limitations, treatment_limitations_chichewa,
    clinical_decision_points, clinical_decision_points_chichewa,
    source, last_reviewed, is_active, created_at, updated_at
) VALUES (
    'af99c307-61e3-4a34-9b11-729c7924805f',
    'Recognising Tuberculosis: What You Need to Know',
    'Kuzindula Matenda a TB: Zomwe Muyenera Kudziwa',
    'tb', 'chw,community', 'warning',
    'Tuberculosis (TB) is an airborne disease caused by bacteria. In Malawi, 18,025 new cases were '
    'reported in 2022. Men aged 35-64 have the highest rates. 66.5% of TB patients are also HIV positive. '
    'TB is curable with 6 months of treatment.',
    'Matenda a TB ndi matenda a mpweya omwe amayambitsa ndi ma bacteria. Ku Malawi, odwala 18,025 '
    'anawonetsedwa mu 2022. Athanzi a 35-64 ndi omwe ali ndi matenda awiri. '
    '66.5% ya odwala TB ali ndi HIV. TB ndi yomwe ndi kuchiritsa ndi mankhwala a masabata 6.',
    '["If you have a cough for more than 2 weeks, go to the health center for TB testing", '
    '"If you have cough + fever + night sweats + weight loss, you need TB testing urgently", '
    '"Complete the full 6 months of TB treatment — do not stop even if you feel better", '
    '"Cover your mouth when coughing — TB spreads through the air", '
    '"Open windows and doors during the day — fresh air reduces TB transmission"]'::jsonb,
    '["Ngati muli ndi kasumiro kwa masabata osachepera 2, pitani ku chipatala kuti muyesedwe TB", '
    '"Ngati muli ndi kasumiro + chifuwa + kutentha usiku + kuchepa kwa thupi, mufunika kuyezedwa TB mwadzidzidzi", '
    '"Malizitsani mankhwala a TB a masabata 6 onse — musasiye ngakhale mukukhutira", '
    '"Adzani pamene mukusumira — TB imafalikira mu mpweya", '
    '"Tsegulani zenera ndi khomo masana — mpweya watsopano umachepetsa kufalikira kwa TB"]'::jsonb,
    '["Don''t share cups, plates, or utensils with someone who has TB", '
    '"Don''t stop TB treatment early — this causes drug-resistant TB which is harder to treat", '
    '"Don''t ignore a cough lasting more than 2 weeks — early detection saves lives", '
    '"Don''t cough into your hands — cover your mouth with your elbow", '
    '"Don''t stay in closed, poorly ventilated rooms — open windows help"]'::jsonb,
    '["Musagawane makompyo, mpira, kapena zida ndi odwala TB", '
    '"Musasiye mankhwala a TB pang''ono — chimenechi chimapangitsa TB yosayamba kuchira", '
    '"Musakane kasumiro komwe kumene kumakhala masabata osachepera 2 — kupeza mwamsanga kumapulumutsa moyo", '
    '"Musasumire mu manja — dzadzani mnzanu ndi thupi lanu", '
    '"Musakhale mu chipinda chotsekedwa komwe mpweya sungalowe — zenera tsegulani zimathandiza"]'::jsonb,
    'Seek TB testing immediately if: cough lasting more than 2 weeks; '
    'coughing up blood; fever that doesn''t go away; night sweats; unexplained weight loss; '
    'extreme tiredness that doesn''t improve.',
    'Yezedwa TB mwadzidzidzi ngati: kasumiro kumene kumakhala masabata osachepera 2; '
    'kusumira magazi; chifuwa komwe sichipita; kutentha usiku; kuchepa kwa thupi chisachitike; '
    'kutopa kwambiri komwe sichikhuta.',
    '["Seek testing at the nearest health center — sputum test is free", '
    '"If diagnosed, start treatment immediately — TB drugs are free", '
    '"Tell your family and close contacts to get tested", '
    '"Take TB drugs on an empty stomach for best absorption", '
    '"Avoid crowded, poorly ventilated spaces during treatment"]'::jsonb,
    '["Yezedwa ku health center pafupi — kuyeza sputum ndi yaulere", '
    '"Ngati mwadziwidwa, yambitsani mankhwala mwadzidzidzi — mankhwala a TB ndi aulere", '
    '"Wuza banja lanu ndi anzakutali kuti ayesenso", '
    '"Mwayeretsani mankhwala a TB pamene mulibe chakudya kuti mugwiritse ntchito bwino", '
    '"Pewani malo ochulukira anthu komwe mpweya sungalowe pomwe muli ndi matenda"]'::jsonb,
    '[{"trigger": "Cough > 2 weeks", "action": "Sputum microscopy or GeneXpert test at health center", "evidence": "TB case detection gap, 18,025 cases in 2022"}, {"trigger": "HIV+ patient with cough", "action": "Immediate TB screening — 66.5% of TB patients are HIV co-infected", "evidence": "Feldacker et al. 2012"}]'::jsonb,
    '[{"trigger": "Kasumiro > masabata 2", "action": "Kuyeza sputum kapena GeneXpert ku health center", "evidence": "Kupezera TB 18,025 odwala mu 2022"}, {"trigger": "Odwala HIV ali ndi kasumiro", "action": "Kuyeza TB mwadzidzidzi — 66.5% ya odwala TB ali ndi HIV", "evidence": "Feldacker et al. 2012"}]'::jsonb,
    '[{"trigger": "Cough > 2 weeks", "action": "Sputum microscopy or GeneXpert test at health center", "evidence": "TB case detection gap, 18,025 cases in 2022"}, {"trigger": "HIV+ patient with cough", "action": "Immediate TB screening — 66.5% of TB patients are HIV co-infected", "evidence": "Feldacker et al. 2012"}]'::jsonb,
    '[{"trigger": "Kasumiro > masabata 2", "action": "Kuyeza sputum kapena GeneXpert ku health center", "evidence": "Kupezera TB 18,025 odwala mu 2022"}, {"trigger": "Odwala HIV ali ndi kasumiro", "action": "Kuyeza TB mwadzidzidzi — 66.5% ya odwala TB ali ndi HIV", "evidence": "Feldacker et al. 2012"}]'::jsonb,
    'Twabi et al. 2025 IJTLD Open; Feldacker et al. 2012 TMIH; WHO TB guidelines',
    '2026-08-26T02:08:29.061061+00:00', TRUE, '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- Malaria: Guide on Child Fever
-- Rerun-safe: drop any older same-title guide first (public list stays deduped).
DELETE FROM self_care_guides WHERE title = 'Child Has Fever? What to Do About Malaria';
INSERT INTO self_care_guides (
    guide_id, title, title_chichewa, category, audience, severity,
    what_it_is, what_it_is_chichewa,
    what_to_do_now, what_to_do_now_chichewa,
    what_not_to_do, what_not_to_do_chichewa,
    when_to_seek_help, when_to_seek_help_chichewa,
    prevention, prevention_chichewa,
    treatment_limitations, treatment_limitations_chichewa,
    clinical_decision_points, clinical_decision_points_chichewa,
    source, last_reviewed, is_active, created_at, updated_at
) VALUES (
    '6e556cb0-efa5-46f3-8478-9e4aec39ffde',
    'Child Has Fever? What to Do About Malaria',
    'Mwana Ali ndi Chifuwa? Zimene Muyenera Kuchira ndi Malungo',
    'malaria', 'chw,community', 'emergency',
    'Malaria is the leading cause of fever in children in Malawi. '
    'National prevalence declined from 44% to 19% but remains a major killer. '
    'In rural Chikhwawa, 57.1% of children had at least one malaria episode per year. '
    'Rainy season (November-April) is highest risk.',
    'Malungo ndi chifuwa chachikulu ku Malawi. '
    'Malungo adachepa kuchoka ku 44% kupita ku 19% koma ali ndi matenda akulu. '
    'Ku Chikhwawa, 57.1% ya ana anali ndi malungo ochepa pang''ono pa chaka. '
    'Nyengo ya mvula (Nov-April) ndi yopulumuka kwambiri.',
    '["Test for malaria immediately with a rapid diagnostic test (mRDT) — do not guess", '
    '"If positive, give ACT (artemisinin-based combination therapy) within 24 hours", '
    '"Give paracetamol for fever — sponging with water helps too", '
    '"Keep the child hydrated — give extra fluids including ORS if diarrhea is present", '
    '"Sleep under a treated bed net every night — especially during rainy season"]'::jsonb,
    '["Yesezani malungo mwadzidzidzi ndi mRDT — musanene kuti ndi malungo", '
    '"Ngati ali ndi malungo, patsani ACT mkati mwa maora 24", '
    '"Patsani paracetamol pa chifuwa — kusamba ndi madzi kumathandizanso", '
    '"Mwana ayenera kukhala ndi madzi okwanila — patsani madzi ozithira ngati ali ndi kunyansa", '
    '"Gonani pansi pa makuta usiku — makamaka mu nyengo ya mvula"]'::jsonb,
    '["Don''t give antibiotics for malaria — they don''t work against parasites", '
    '"Don''t delay treatment — malaria can become severe within hours in children", '
    '"Don''t use expired drugs — check the date on ACT packaging", '
    '"Don''t rely on herbal remedies alone for malaria — they delay life-saving treatment", '
    '"Don''t skip the bed net because it''s hot — the risk of malaria is worse than discomfort"]'::jsonb,
    '["Musapatsi mankhwala a matenda a mankhwala pa malungo — samagwira ntchito ndi ma parasites", '
    '"Musachedwe kuchiritsa — malungo amatha kukhala owopsya mkati mwa maora kwa ana", '
    '"Musagwiritse ntchito mankhwala owonjezera — onetsetsani tsiku pa kapaketi ya ACT", '
    '"Musayembekezere mankhwala a chikhalidwe kokha pa malungo — amachedwetsa chithandizo chamoyo", '
    '"Musasiye makuta chifukwa chotentha — ngozi ya malungo ndi yochulukira kuposa kuotentha"]'::jsonb,
    'Seek emergency care immediately if: child under 5 has fever; '
    'child is not eating or drinking; child is unusually sleepy or irritable; '
    'child has convulsions or seizures; fever persists more than 48 hours after starting ACT.',
    'Funsani thandizo la pachuma mwadzidzidzi ngati: mwana wosakwana miyesi 5 ali ndi chifuwa; '
    'mwana sakufuna kudya kapena kumwa; mwana ali ndi tulo tachilendo kapena kukwiya; '
    'mwana ali ndi convulsions; chifuwa kumene chimapitirira masiku 2 atayamba ACT.',
    '["Test every fever for malaria — don''t assume it''s just a cold", '
    '"ACTs are free at health centers — never buy from unofficial sources", '
    '"Bed nets work best when everyone in the house uses one — community protection", '
    '"Pregnant women should use bed nets and attend ANC — malaria in pregnancy is dangerous", '
    '"Report if ACTs are out of stock at your facility — stockouts cost lives"]'::jsonb,
    '["Yesezani chifuwa chilichonse kwa malungo — musanene kuti ndi matenda a mpweya kokha", '
    '"ACT ndi yaulere ku health centers — musagule kwa osagulitsa osiyana", '
    '"Makuta amagwira ntchito bwino ngati anthu onse m''nyumba amagwiritsa ntchito", '
    '"Amayi ali ndi mimba ayenera kugwiritsa ntchito makuta ndikupita ku ANC — malungo mu mimba ndi owopsya", '
    '"Lembani ngati ACT zakwana pa facility yanu — zakwanira zimapotsa moyo"]'::jsonb,
    '[{"trigger": "Child < 5 with fever", "action": "Immediate mRDT test,ACT if positive, paracetamol, monitor", "evidence": "57.1% cumulative incidence in Chikhwawa"}, {"trigger": "Fever persists > 48h on ACT", "action": "Re-evaluate for treatment failure, consider referral", "evidence": "ACT resistance monitoring"}]'::jsonb,
    '[{"trigger": "Mwana wosakwana miyesi 5 ali ndi chifuwa", "action": "Yesezani mRDT mwadzidzidzi, ACT ngati ali ndi malungo, paracetamol, yang''anirani", "evidence": "57.1% ya ana ali ndi malungo mu chaka chimodzi"}, {"trigger": "Chifuwa kumene chimapitirira masiku 2 pa ACT", "action": "Bwererani kuwunira, ganizirani kuti mankhwala sangagwire ntchito, tumizani ku chipatala", "evidence": "Kuyeza kukana mankhwala"}]'::jsonb,
    '[{"trigger": "Child < 5 with fever", "action": "Immediate mRDT test, ACT if positive, paracetamol, monitor", "evidence": "57.1% cumulative incidence in Chikhwawa"}, {"trigger": "Fever persists > 48h on ACT", "action": "Re-evaluate for treatment failure, consider referral", "evidence": "ACT resistance monitoring"}]'::jsonb,
    '[{"trigger": "Mwana wosakwana miyesi 5 ali ndi chifuwa", "action": "Yesezani mRDT mwadzidzidzi, ACT ngati ali ndi malungo, paracetamol, yang''anirani", "evidence": "57.1% ya ana ali ndi malungo mu chaka chimodzi"}, {"trigger": "Chifuwa kumene chimapitirira masiku 2 pa ACT", "action": "Bwererani kuwunira, ganizirani kuti mankhwala sangagwire ntchito, tumizani ku chipatala", "evidence": "Kuyeza kukana mankhwala"}]'::jsonb,
    'Kabaghe et al. 2018 Parasites & Vectors; Boudova et al. 2015 Malaria Journal; WHO malaria guidelines',
    '2026-08-26T02:08:29.061061+00:00', TRUE, '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;


