-- Nutrition Talk: Feeding Our Children Right
INSERT INTO community_health_talks (
    talk_id, title, title_chichewa, study_id,
    duration_minutes, talking_points, talking_points_chichewa,
    discussion_questions,
    pledge_card_text, pledge_card_text_chichewa,
    health_topic, audience, status, created_at, updated_at
) VALUES (
    'c7698395-462d-490e-823b-83cc6f186a31',
    'Feeding Our Children Right: What Research Tells Us',
    'Kudyetsa Ana Athu Mwachizolowezi: Zomwe Kafukufuku Amawonetsa',
    '65320254-bbfd-4251-b852-ea77716766b9',
    15,
    '["Open: How many children under 2 do you know who are not growing well? (normalise the discussion)", '
    '"Fact 1: 30.8% of children under 2 in Malawi are stunted — nearly 1 in 3", '
    '"Fact 2: Only 32% of children get foods from 4+ food groups — most children are underfed", '
    '"Fact 3: 40% of mothers stop exclusive breastfeeding before 6 months — this harms the baby", '
    '"What to do: Breastfeed exclusively for 6 months, then add diverse foods while continuing to breastfeed", '
    '"Warning signs: If a child is not gaining weight, is always sick, or refuses to eat — visit the health center", '
    '"Community action: Support mothers — help them find diverse foods, encourage breastfeeding in public", '
    '"Close: Good nutrition today means healthy adults tomorrow — it starts with what we feed our children"]'::jsonb,
    '["Tiyambire — kodi muli ndi ana osakwana miyesi 5 okhutira? (tichotsenepo manyazi)", '
    '"Zilanga 1: 30.8% ya ana ku Malawi ndi okhutira — pafupifupi 1 kwa 3", '
    '"Zilanga 2: Okha 32% ya ana amalandira zakudya kuchokera kwa magulu 4+ — ambiri samadye bwino", '
    '"Zilanga 3: 40% ya amayi amasiya kudyetsa mphenyo yokha isanafike miyesi 6 — chimenechi chimawononga mwana", '
    '"Zimene muyenera kuchira: Dyetsani mphenyo yokha kwa masabata 6, kenako onjezani zakudya zosiyanasiyana", '
    '"Zizindikiro zoopsya: Ngati mwana saukula, amamankhwala nthawi zonse, kapena sakufuna kudya — pitani ku chipatala", '
    '"Chithandizo cha m''mudzi: Thandizani amayi — mwawthandize kupezera zakudya, limbikitsani kudyetsa mphenyo pasanakhalepo", '
    '"Makalata: Zakudya zabwino lero zimatanthauza athanzi a mawa — tiyambire ndi zomwe timadyetsa ana athu"]'::jsonb,
    '["What foods are available in your village that could improve children''s diets?", '
    '"Why do some mothers stop breastfeeding early? What can we do to help?", '
    '"How can the community support mothers who are breastfeeding in public?", '
    '"What barriers prevent families from taking children for growth monitoring?"]'::jsonb,
    'I pledge to feed my children well by: '
    '(1) Breastfeeding exclusively for 6 months; '
    '(2) Adding diverse foods from 4+ food groups after 6 months; '
    '(3) Taking my child for growth monitoring every month; '
    '(4) Not giving water to babies under 6 months; '
    '(5) Seeking help early if my child is not growing well.',
    'Ndimalira ndi kudyetsa ana anga mwachizolowezi ndi: '
    '(1) Kudyetsa mphenyo yokha kwa masabata 6; '
    '(2) Kuyambitsani zakudya zosiyanasiyana kuchokera kwa magulu 4+ patapita miyesi 6; '
    '(3) Kubweretsa mwana ku chipatala kuwunira kukula kwa mwezi ndi mwezi; '
    '(4) Kusapatsa madzi ana osakwana miyesi 6; '
    '(5) Kufunsa thandizo mwamsanga ngati mwana saukula.',
    'nutrition', 'community', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- TB Talk: Knowing TB
INSERT INTO community_health_talks (
    talk_id, title, title_chichewa, study_id,
    duration_minutes, talking_points, talking_points_chichewa,
    discussion_questions,
    pledge_card_text, pledge_card_text_chichewa,
    health_topic, audience, status, created_at, updated_at
) VALUES (
    'f29ff39f-f5d3-4594-8aca-6b8183bc5a41',
    'TB in Our Community: Finding and Curing It',
    'TB m''Mudzi Mwathu: Kupezera ndi Kuchira',
    'dc2c3acf-f6a9-4231-a06e-aa9cc7946ebb',
    15,
    '["Open: Has anyone here had TB or known someone with TB? (normalise the conversation)", '
    '"Fact 1: In 2022, 18,025 Malawians were diagnosed with TB — it is still very common", '
    '"Fact 2: Men aged 35-64 have the highest TB rates — fathers and grandfathers are most at risk", '
    '"Fact 3: 66.5% of TB patients are also HIV positive — if you have HIV, get tested for TB", '
    '"Symptoms: Cough for more than 2 weeks, fever, night sweats, weight loss, tiredness", '
    '"What to do: Go to the health center for a free sputum test — early detection saves lives", '
    '"Treatment: TB treatment takes 6 months — you must complete ALL the medicine, even if you feel better", '
    '"Prevention: Open windows, cover your mouth when coughing, get tested if you have HIV", '
    '"Close: TB is curable — but only if we find it early and treat it fully"]'::jsonb,
    '["Tiyambire — kodi muli ndi odwala TB kapena mwadziwa odwala TB? (tichotsenepo manyazi)", '
    '"Zilanga 1: Mu 2022, odwala 18,025 a ku Malawi adawonetsedwa ali ndi TB — ali ndi matenda ambiri", '
    '"Zilanga 2: Athanzi a 35-64 ndi omwe ali ndi TB kwambiri — atate ndi gogo ndi omwe ali pangozi", '
    '"Zilanga 3: 66.5% ya odwala TB ali ndi HIV — ngati muli ndi HIV, yesedwa TB", '
    '"Zizindikiro: Kasumiro kwa masabata osachepera 2, chifuwa, kutentha usiku, kuchepa kwa thupi, kutopa", '
    '"Zimene muyenera kuchira: Pitani ku chipatala ku yesedwa sputum — kupeza mwamsanga kumapulumutsa moyo", '
    '"Chithandizo: Chithandizo a TB ndi masabata 6 — muyenera malizitsa mankhwala onse, ngakhale mukukhutira", '
    '"Kupewa: Tsegulani zenera, dzadzani pamene mukusumira, yesedwa ngati muli ndi HIV", '
    '"Makalata: TB ndi yomwe ndi kuchiritsa — koma tikapeza mwamsanga ndi kuchiritsa motere kokha"]'::jsonb,
    '["Why do you think men aged 35-64 have the highest TB rates?", '
    '"What prevents people from completing the full 6 months of TB treatment?", '
    '"How can our community support TB patients to finish their treatment?", '
    '"What can we do to improve ventilation in our homes and meeting places?"]'::jsonb,
    'I pledge to fight TB by: '
    '(1) Going to the health center if I have a cough lasting more than 2 weeks; '
    '(2) Completing the full 6 months of TB treatment if diagnosed; '
    '(3) Covering my mouth when I cough and opening windows at home; '
    '(4) Telling my family and friends about TB symptoms; '
    '(5) Supporting my neighbours who are being treated for TB.',
    'Ndimalira ndi kukana TB ndi: '
    '(1) Kupita ku chipatala ngati ndili ndi kasumiro kwa masabata osachepera 2; '
    '(2) Kuyambitsa mankhwala onse a masabata 6 ngati ndadziwidwa; '
    '(3) Kudzadza pamene ndikusumira ndi kutsegula zenera m''nyumba; '
    '(4) Kuwuza banja ndi anzanga za zizindikiro za TB; '
    '(5) Kuthandiza anzanga omwe ali ndi mankhwala a TB.',
    'tb', 'community', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- Malaria Talk: Bed Nets and Fever
INSERT INTO community_health_talks (
    talk_id, title, title_chichewa, study_id,
    duration_minutes, talking_points, talking_points_chichewa,
    discussion_questions,
    pledge_card_text, pledge_card_text_chichewa,
    health_topic, audience, status, created_at, updated_at
) VALUES (
    '56b9be88-2e18-43df-b385-490ae8a88084',
    'Malaria Is Decreasing — But Not Gone: Keep Fighting',
    'Malungo Akuchepa — Koma Sangathe: Pitirizani Ndende',
    '6230872c-4510-4dd9-aa2a-2c7bcbd697b2',
    15,
    '["Open: How many children in this village had malaria last year? (count hands)", '
    '"Fact 1: Malaria in pregnant women declined from 28% to 15% after bed net campaigns — progress is real", '
    '"Fact 2: But 57% of children in rural areas still get malaria at least once a year", '
    '"Fact 3: Bed nets work best when EVERYONE uses them — community protection matters", '
    '"Rainy season is worst: November to April — be extra vigilant with nets", '
    '"Fever action: Test with mRDT first, then ACT within 24 hours — don''t guess, don''t delay", '
    '"Prevention: Sleep under nets, empty standing water, get vaccinated when available", '
    '"Close: Malaria is going down because of our efforts — let''s keep it going"]'::jsonb,
    '["Tiyambire — kodi ana angati m''mudzi mwathu anali ndi malungo chaka chatha? (utchinjiriza mano)", '
    '"Zilanga 1: Malungo kwa amayi ali ndi mimba adachepa kuchoka ku 28% kupita ku 15% — kukula kulipo", '
    '"Zilanga 2: Koma 57% ya ana ku mzano ali ndi malungo ochepa pang''ono pa chaka chimodzi", '
    '"Zilanga 3: Makuta amagwira ntchito bwino ngati anthu ONSE amagwiritsa ntchito — chitetezo cha gulu ndi chofunika", '
    '"Nyengo yoyipa: Novembala kuya Apulo — pitirizani kugwiritsa ntchito makuta", '
    '"Chifuwa: Yesedwa ndi mRDT首先, kenako ACT mkati mwa maora 24 — musanene, musachedwe", '
    '"Kupewa: Gonani pansi pa makuta, chotsani madzi, dyzani rotha ngati ilipo", '
    '"Makalata: Malungo akuchepa chifukwa cha kuchita kwathu — tiyeni tipitirize"]'::jsonb,
    '["Why do some people stop using bed nets after the campaign ends?", '
    '"What makes it hard to sleep under a net in the hot season?", '
    '"How can we help mothers get to ANC early for malaria prevention?", '
    '"What standing water sources are near our homes that breed mosquitoes?"]'::jsonb,
    'I pledge to prevent malaria by: '
    '(1) Sleeping under a treated bed net every night, all year; '
    '(2) Taking my child for a malaria test within 24 hours of fever; '
    '(3) Emptying standing water around my home; '
    '(4) Making sure pregnant women in my family use bed nets; '
    '(5) Taking my pregnant wife to ANC for malaria prevention.',
    'Ndimalira ndi kupewa malungo ndi: '
    '(1) Kugonera pansi pa makuta usiku, zaka zonse; '
    '(2) Kubweretsa mwana ku yesedwa malungo mkati mwa maora 24 ali ndi chifuwa; '
    '(3) Kuchotsani madzi ozizira pafupi ndi nyumba yathu; '
    '(4) Onetsetsani kuti amayi ali ndi mimba m''banja mwanu amagwiritsa ntchito makuta; '
    '(5) Kubweretsa mkazi wanga ku ANC kupewa malungo.',
    'malaria', 'community', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;

-- HIV Talk: Know Your Status
INSERT INTO community_health_talks (
    talk_id, title, title_chichewa, study_id,
    duration_minutes, talking_points, talking_points_chichewa,
    discussion_questions,
    pledge_card_text, pledge_card_text_chichewa,
    health_topic, audience, status, created_at, updated_at
) VALUES (
    'b23c56a6-a28e-47ee-b8ec-de0719ad7af6',
    'Know Your Status: The First Step to a Healthy Life',
    'Dziwani Mwatsimikizi: Sitepu Yoyamba Kupita ku Umoyo Wabwino',
    '0d03a7ef-4313-4b75-9e1e-187182dfac62',
    15,
    '["Open: When was the last time you tested for HIV? (encourage honesty, not shame)", '
    '"Fact 1: Malawi is making progress toward 95-95-95 — but we need everyone to get tested", '
    '"Fact 2: If you know your status and start treatment early, you can live a long, healthy life", '
    '"Fact 3: New prevention options like injectable cabotegravir are now available in Malawi", '
    '"Testing is free and confidential at all health facilities", '
    '"If positive: Start ART immediately — take it every day — it suppresses the virus and prevents transmission", '
    '"Couples testing: Bring your partner — knowing together strengthens your relationship", '
    '"For young people: HIV does not discriminate — get tested regardless of who you are", '
    '"Close: Knowing your status is not about shame — it''s about taking control of your health"]'::jsonb,
    '["Tiyambire — mwamakwira nthawi liti ku yesedwa HIV? (limbikitsani chowonadi, osati manyazi)", '
    '"Zilanga 1: Malawi akukula kufika ku 95-95-95 — koma tiyenera onse tiyesedwe", '
    '"Zilanga 2: Ngati mudziwa chowonadi ndi kuyamba chithandizo mwamsanga, mutha kukhala ndi umoyo wautali", '
    '"Zilanga 3: Njira zatsopano za chitetezo ngati cabotegravir zaperekedwa kale ku Malawi", '
    '"Kuyeza ndi yaulere ndi zachinsisi ku ma facility onse a zaumoyo", '
    '"Ngati muli ndi HIV: Yambitsani ART mwadzidzidzi — mwayeretsani tsiku lililonse — imagwira ntchito", '
    '"Kuyeza pamodzi: Bweretsani mnzanu — kudziwa limodzi kumathandiza ubale", '
    '"Kwa achinyamata: HIV samasankha — yesedwa ngakhale ndani muli", '
    '"Makalata: Kudziwa chowonadi sikunena manyazi — ndi kugwira ntchito pa umoyo wanu"]'::jsonb,
    '["What are the barriers to HIV testing in our community?", '
    '"How can we encourage young people to get tested without fear?", '
    '"What support do people living with HIV need from their communities?", '
    '"How can we reduce stigma against people on ART?"]'::jsonb,
    'I pledge to protect myself and my family from HIV by: '
    '(1) Getting tested for HIV and knowing my status; '
    '(2) Encouraging my partner to get tested with me; '
    '(3) If positive, starting ART immediately and taking it every day; '
    '(4) Talking openly with my family about HIV prevention; '
    '(5) Supporting neighbours who are living with HIV.',
    'Ndimalira ndi kudzichepetsa ndi kuchotsa banja langa ku HIV ndi: '
    '(1) Kuyezedwa HIV ndi kudziwa chowonadi changa; '
    '(2) Kukupatsa mnzanga moyo kuti ayesenwe pamodzi ndi ine; '
    '(3) Ngati ndili ndi HIV, yambitsani ART mwadzidzidzi ndi kuyitenga tsiku lililonse; '
    '(4) Kukambirana ndi banja langa mwachimwemwe za kupewa HIV; '
    '(5) Kuthandiza anzanga omwe ali ndi HIV.',
    'hiv', 'community', 'approved', '2026-08-26T02:08:29.061061+00:00', '2026-08-26T02:08:29.061061+00:00'
) ON CONFLICT DO NOTHING;


