-- VERIFICATION QUERIES
-- ════════════════════════════════════════════════════════════════

-- Study count by topic
SELECT health_topic, COUNT(*) AS studies FROM research_studies GROUP BY health_topic ORDER BY studies DESC;

-- Assets by type
SELECT asset_type, COUNT(*) AS count FROM knowledge_assets GROUP BY asset_type;

-- Guides by category
SELECT category, title, severity FROM self_care_guides;

-- Talks by topic
SELECT health_topic, title FROM community_health_talks;

-- Total counts
SELECT 'studies' AS entity, COUNT(*) AS total FROM research_studies
UNION ALL SELECT 'assets', COUNT(*) FROM knowledge_assets
UNION ALL SELECT 'guides', COUNT(*) FROM self_care_guides
UNION ALL SELECT 'talks', COUNT(*) FROM community_health_talks;
